/* =========================================================
   CONFIGURATION & STATE
========================================================= */
const HERO_PHRASES = [
  "Building Fast Websites!",
  "Crafting Modern UIs!",
  "Responsive Web Experiences!",
];

const TYPING_SPEED = 120;
const DELETING_SPEED = 60;
const PAUSE_DURATION = 1800;

let phraseIndex = 0;
let characterIndex = 0;
let isDeleting = false;
let typingTimer = null;

/* =========================================================
   THEME TOGGLE (DARK / LIGHT MODE)
========================================================= */
function applySavedTheme() {
  if (localStorage.getItem("lightMode") === "true") {
    document.body.classList.add("light-mode");
  }
}

function initializeThemeToggle() {
  const themeToggleInput = document.getElementById("theme-toggle");
  if (!themeToggleInput) return;

  themeToggleInput.checked = document.body.classList.contains("light-mode");

  themeToggleInput.addEventListener("change", () => {
    document.body.classList.toggle("light-mode");
    localStorage.setItem(
      "lightMode",
      document.body.classList.contains("light-mode")
    );
  });
}

/* =========================================================
   MOBILE & TABLET NAVIGATION DROPDOWN
========================================================= */
function initializeMobileMenu() {
  const menuToggleButton = document.getElementById("mobile-menu-toggle");
  const navigationMenu = document.getElementById("navigation-menu");
  if (!menuToggleButton || !navigationMenu) return;

  const navigationLinks = navigationMenu.querySelectorAll("a");

  const closeMenu = () => {
    navigationMenu.classList.remove("navigation-active");
    menuToggleButton.classList.replace("fa-xmark", "fa-bars");
    menuToggleButton.setAttribute("aria-expanded", "false");
  };

  const toggleMenu = () => {
    const isOpen = navigationMenu.classList.toggle("navigation-active");
    menuToggleButton.classList.toggle("fa-bars", !isOpen);
    menuToggleButton.classList.toggle("fa-xmark", isOpen);
    menuToggleButton.setAttribute("aria-expanded", String(isOpen));
  };

  menuToggleButton.addEventListener("click", toggleMenu);

  menuToggleButton.addEventListener("keydown", (event) => {
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      toggleMenu();
    }
  });

  navigationLinks.forEach((link) => link.addEventListener("click", closeMenu));

  // Close dropdown when clicking outside
  document.addEventListener("click", (event) => {
    if (
      navigationMenu.classList.contains("navigation-active") &&
      !navigationMenu.contains(event.target) &&
      !menuToggleButton.contains(event.target)
    ) {
      closeMenu();
    }
  });

  // Close dropdown on Escape key
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && navigationMenu.classList.contains("navigation-active")) {
      closeMenu();
    }
  });
}

/* =========================================================
   ACTIVE NAVIGATION SCROLL SPY
========================================================= */
function initializeScrollSpy() {
  const pageSections = Array.from(document.querySelectorAll("section[id]"));
  const navigationLinks = document.querySelectorAll(".navigation-link");
  if (!pageSections.length || !navigationLinks.length) return;

  const setActiveLink = (sectionId) => {
    const targetHref = `#${sectionId}`;
    navigationLinks.forEach((link) => {
      const isMatch = link.getAttribute("href") === targetHref;
      link.classList.toggle("active-link", isMatch);

      if (isMatch) {
        link.setAttribute("aria-current", "page");
      } else {
        link.removeAttribute("aria-current");
      }
    });
  };

  const updateActiveSection = () => {
    const scrollTop = window.scrollY || document.documentElement.scrollTop || 0;
    const viewportBottom = scrollTop + window.innerHeight;
    const documentHeight = document.documentElement.scrollHeight;

    // Highlight last section when scrolled to bottom of page
    if (viewportBottom >= documentHeight - 20) {
      setActiveLink(pageSections[pageSections.length - 1].id);
      return;
    }

    // Use tighter offset in short landscape viewports
    const navbarClearance = window.innerHeight <= 600 ? 75 : 115;
    const triggerOffset = scrollTop + navbarClearance;
    let currentSectionId = pageSections[0].id;

    for (const section of pageSections) {
      if (triggerOffset >= section.offsetTop) {
        currentSectionId = section.id;
      } else {
        break;
      }
    }

    setActiveLink(currentSectionId);
  };

  updateActiveSection();
  window.addEventListener("scroll", updateActiveSection, { passive: true });
  window.addEventListener("resize", updateActiveSection, { passive: true });
}

/* =========================================================
   HERO TYPING ANIMATION
========================================================= */
function scheduleTyping(delay) {
  clearTimeout(typingTimer);
  typingTimer = setTimeout(runTypingAnimation, delay);
}

function runTypingAnimation() {
  const typingTarget = document.querySelector(".typing-text");
  if (!typingTarget || !document.body.contains(typingTarget)) {
    clearTimeout(typingTimer);
    return;
  }

  const currentPhrase = HERO_PHRASES[phraseIndex];
  characterIndex += isDeleting ? -1 : 1;
  typingTarget.textContent = currentPhrase.slice(0, characterIndex);

  if (!isDeleting && characterIndex === currentPhrase.length) {
    isDeleting = true;
    scheduleTyping(PAUSE_DURATION);
    return;
  }

  if (isDeleting && characterIndex === 0) {
    isDeleting = false;
    phraseIndex = (phraseIndex + 1) % HERO_PHRASES.length;
  }

  scheduleTyping(isDeleting ? DELETING_SPEED : TYPING_SPEED);
}

/* =========================================================
   PROJECT CARD SEGMENTED TABS
========================================================= */
function initializeProjectTabs() {
  document.addEventListener("click", (event) => {
    const tabButton = event.target.closest(".project-tab-button");
    if (!tabButton) return;

    event.preventDefault();
    const projectCard = tabButton.closest(".project-card");
    if (!projectCard) return;

    const selectedTab = tabButton.getAttribute("data-tab");

    projectCard.querySelectorAll(".project-tab-button").forEach((button) => {
      button.classList.remove("active");
      button.setAttribute("aria-selected", "false");
    });

    projectCard.querySelectorAll(".project-tab-panel").forEach((panel) => {
      panel.classList.remove("active");
    });

    tabButton.classList.add("active");
    tabButton.setAttribute("aria-selected", "true");

    const activePanel = projectCard.querySelector(
      `.project-tab-panel[data-pane="${selectedTab}"]`
    );
    if (activePanel) {
      activePanel.classList.add("active");
    }
  });
}

/* =========================================================
   PROJECTS CAROUSEL & TOUCH PREVIEW SCROLL
========================================================= */
function initializeProjectCarousel() {
  const projectsTrack = document.getElementById("projects-track");
  const previousButton = document.getElementById("carousel-previous");
  const nextButton = document.getElementById("carousel-next");
  const carouselDots = document.querySelectorAll(".carousel-dot");

  // Tap-to-scroll full-page previews on touch devices
  document.querySelectorAll(".project-preview").forEach((previewBox) => {
    previewBox.addEventListener("click", () => {
      const previewImage = previewBox.querySelector("img");
      if (!previewImage) return;

      const isScrolled = previewBox.classList.toggle("is-scrolled");
      if (isScrolled) {
        const overflowDistance = Math.max(
          0,
          previewImage.offsetHeight - previewBox.clientHeight
        );
        previewImage.style.transform = `translateY(-${overflowDistance}px)`;
      } else {
        previewImage.style.transform = "";
      }
    });
  });

  if (!projectsTrack || !previousButton || !nextButton || !carouselDots.length) return;

  const projectCards = projectsTrack.querySelectorAll(".project-card");
  if (!projectCards.length) return;

  let activeSlideIndex = 0;

  const resetPreviewScrolls = () => {
    document.querySelectorAll(".project-preview.is-scrolled").forEach((box) => {
      box.classList.remove("is-scrolled");
      const img = box.querySelector("img");
      if (img) img.style.transform = "";
    });
  };

  const updateCarouselDots = (index) => {
    carouselDots.forEach((dot, dotIndex) => {
      dot.classList.toggle("active", dotIndex === index);
    });
  };

  const goToSlide = (index) => {
    resetPreviewScrolls();
    activeSlideIndex = (index + projectCards.length) % projectCards.length;
    const baseOffset = projectCards[0].offsetLeft;
    const targetLeft = projectCards[activeSlideIndex].offsetLeft - baseOffset;

    projectsTrack.scrollTo({
      left: targetLeft,
      behavior: "smooth",
    });

    updateCarouselDots(activeSlideIndex);
  };

  nextButton.addEventListener("click", () => goToSlide(activeSlideIndex + 1));
  previousButton.addEventListener("click", () => goToSlide(activeSlideIndex - 1));

  carouselDots.forEach((dot, index) => {
    dot.addEventListener("click", () => goToSlide(index));
  });

  // Sync active indicator dot when swiping manually
  let scrollTimer;
  projectsTrack.addEventListener(
    "scroll",
    () => {
      clearTimeout(scrollTimer);
      scrollTimer = setTimeout(() => {
        const slideStep =
          projectCards.length > 1
            ? projectCards[1].offsetLeft - projectCards[0].offsetLeft
            : projectsTrack.clientWidth;

        if (!slideStep) return;

        const newIndex = Math.round(projectsTrack.scrollLeft / slideStep);
        if (
          newIndex >= 0 &&
          newIndex < projectCards.length &&
          newIndex !== activeSlideIndex
        ) {
          resetPreviewScrolls();
          activeSlideIndex = newIndex;
          updateCarouselDots(activeSlideIndex);
        }
      }, 60);
    },
    { passive: true }
  );
}

/* =========================================================
   CUSTOM OVERLAY SCROLLBAR (DESKTOP)
========================================================= */
function initializeCustomScrollbar() {
  const rootElement = document.documentElement;
  const scrollbarContainer = document.getElementById("custom-scrollbar");
  const scrollbarTrack = document.getElementById("custom-scrollbar-track");
  const scrollbarThumb = document.getElementById("custom-scrollbar-thumb");
  const upArrowButton = document.getElementById("custom-scrollbar-up");
  const downArrowButton = document.getElementById("custom-scrollbar-down");

  if (
    !scrollbarContainer ||
    !scrollbarTrack ||
    !scrollbarThumb ||
    !upArrowButton ||
    !downArrowButton
  ) {
    return;
  }

  let isDraggingThumb = false;
  let dragStartY = 0;
  let dragStartScrollTop = 0;

  const syncScrollbarPosition = () => {
    const scrollTop = window.scrollY || rootElement.scrollTop || 0;
    const scrollHeight = rootElement.scrollHeight;
    const clientHeight = rootElement.clientHeight;
    const maxScrollTop = Math.max(0, scrollHeight - clientHeight);

    const isAtTop = scrollTop <= 2;
    const isAtBottom = maxScrollTop <= 2 || scrollTop >= maxScrollTop - 2;

    scrollbarContainer.classList.toggle("at-top", isAtTop);
    scrollbarContainer.classList.toggle("at-bottom", isAtBottom);

    const trackHeight = scrollbarTrack.clientHeight;
    const thumbHeight = Math.max(
      36,
      Math.round((clientHeight / Math.max(scrollHeight, 1)) * trackHeight)
    );
    const maxThumbOffset = Math.max(0, trackHeight - thumbHeight);
    const thumbOffset =
      maxScrollTop > 0 ? (scrollTop / maxScrollTop) * maxThumbOffset : 0;

    scrollbarThumb.style.height = `${thumbHeight}px`;
    scrollbarThumb.style.transform = `translateY(${thumbOffset}px)`;
  };

  upArrowButton.addEventListener("click", () => {
    window.scrollBy({ top: -window.innerHeight * 0.75, behavior: "smooth" });
  });

  downArrowButton.addEventListener("click", () => {
    window.scrollBy({ top: window.innerHeight * 0.75, behavior: "smooth" });
  });

  scrollbarTrack.addEventListener("mousedown", (event) => {
    if (event.target === scrollbarThumb) return;
    const trackRect = scrollbarTrack.getBoundingClientRect();
    const clickRatio = (event.clientY - trackRect.top) / trackRect.height;
    const maxScrollTop = rootElement.scrollHeight - rootElement.clientHeight;
    window.scrollTo({ top: clickRatio * maxScrollTop, behavior: "smooth" });
  });

  scrollbarThumb.addEventListener("mousedown", (event) => {
    event.preventDefault();
    isDraggingThumb = true;
    dragStartY = event.clientY;
    dragStartScrollTop = window.scrollY || rootElement.scrollTop || 0;
    scrollbarContainer.classList.add("is-dragging");
  });

  window.addEventListener("mousemove", (event) => {
    if (!isDraggingThumb) return;
    const deltaY = event.clientY - dragStartY;
    const availableTrack =
      scrollbarTrack.clientHeight - scrollbarThumb.offsetHeight;
    const maxScrollTop = rootElement.scrollHeight - rootElement.clientHeight;
    if (availableTrack > 0 && maxScrollTop > 0) {
      window.scrollTo(
        0,
        dragStartScrollTop + (deltaY / availableTrack) * maxScrollTop
      );
    }
  });

  window.addEventListener("mouseup", () => {
    if (!isDraggingThumb) return;
    isDraggingThumb = false;
    scrollbarContainer.classList.remove("is-dragging");
  });

  scrollbarThumb.addEventListener(
    "touchstart",
    (event) => {
      if (!event.touches.length) return;
      isDraggingThumb = true;
      dragStartY = event.touches[0].clientY;
      dragStartScrollTop = window.scrollY || rootElement.scrollTop || 0;
      scrollbarContainer.classList.add("is-dragging");
    },
    { passive: true }
  );

  window.addEventListener(
    "touchmove",
    (event) => {
      if (!isDraggingThumb || !event.touches.length) return;
      const deltaY = event.touches[0].clientY - dragStartY;
      const availableTrack =
        scrollbarTrack.clientHeight - scrollbarThumb.offsetHeight;
      const maxScrollTop = rootElement.scrollHeight - rootElement.clientHeight;
      if (availableTrack > 0 && maxScrollTop > 0) {
        window.scrollTo(
          0,
          dragStartScrollTop + (deltaY / availableTrack) * maxScrollTop
        );
      }
    },
    { passive: true }
  );

  window.addEventListener("touchend", () => {
    if (!isDraggingThumb) return;
    isDraggingThumb = false;
    scrollbarContainer.classList.remove("is-dragging");
  });

  syncScrollbarPosition();
  window.addEventListener("scroll", syncScrollbarPosition, { passive: true });
  window.addEventListener("resize", syncScrollbarPosition, { passive: true });
  window.addEventListener("load", syncScrollbarPosition);
}

/* =========================================================
   FOOTER YEAR & PRELOADER CONTROL
========================================================= */
function updateFooterYear() {
  const currentYearElement = document.getElementById("current-year");
  if (currentYearElement) {
    currentYearElement.textContent = new Date().getFullYear();
  }
}

function hidePreloader() {
  const preloaderElement = document.getElementById("preloader");
  if (preloaderElement && !preloaderElement.classList.contains("hide")) {
    preloaderElement.classList.add("hide");
    requestAnimationFrame(() => {
      window.dispatchEvent(new Event("resize"));
    });
  }
}

/* =========================================================
   INITIALIZATION
========================================================= */
applySavedTheme();

document.addEventListener("DOMContentLoaded", () => {
  if (typeof AOS !== "undefined") {
    AOS.init({
      once: false,
      duration: 500,
    });
  }

  initializeThemeToggle();
  initializeMobileMenu();
  initializeScrollSpy();
  initializeProjectTabs();
  initializeProjectCarousel();
  initializeCustomScrollbar();
  updateFooterYear();
  scheduleTyping(TYPING_SPEED);
});

window.addEventListener("load", () => {
  setTimeout(hidePreloader, 500);

  if (typeof AOS !== "undefined") {
    setTimeout(() => AOS.refresh(), 600);
  }
});

// Fallback timeout in case an external asset takes too long
setTimeout(hidePreloader, 3000);

window.addEventListener("beforeunload", () => {
  clearTimeout(typingTimer);
});